style.css:
@-moz-document url-prefix("https://www.bandlab.com/studio") {
/* Base FL Studio Grey Tones */
    :root {
        --bg-main: #1e222b !important;
        --bg-darker: #15181f !important;
        --bg-lighter: #2c323f !important;
        
        --accent-red: #ff3b30 !important;
        --accent-blue: #007aff !important;
        --accent-green: #34c759 !important;
        
        --text-main: #e5e5e7 !important;
        --text-muted: #8e8e93 !important;
    }

    /* Main Background & Panels */
    body, .app-container, .mix-editor, .track-list {
        background-color: var(--bg-main) !important;
        color: var(--text-main) !important;
    }

    /* Header */
    header, .transport-bar, .top-bar {
        background-color: var(--bg-darker) !important;
        border-bottom: 1px solid var(--accent-blue) !important;
    }

    /* Red Accents */
    .btn-record, .is-recording, .active-red {
        background-color: var(--accent-red) !important;
        color: #ffffff !important;
    }

    /* Green Accents */
    .btn-play, .is-playing, .active-green, .solo-button.active {
        background-color: var(--accent-green) !important;
        color: #000000 !important;
    }

    /* Blue Accents */
    .track-item.is-selected, .grid-cell.active, .timeline-cursor {
        border-color: var(--accent-blue) !important;
        background-color: rgba(0, 122, 255, 0.15) !important;
    }

    /* Sliders */
    input[type="range"]::-webkit-slider-thumb {
        background: var(--accent-blue) !important;
    }
    
    .volume-meter .level-bar {
        background: linear-gradient(to right, var(--accent-green), var(--accent-red)) !important;
    }

    /* Text */
    p, span, h1, h2, h3 {
        color: var(--text-main);
    }
    .muted-text {
        color: var(--text-muted) !important;
    }
}
